def total_gramme(ch):
    e = ch.find(" ")
    if e==-1 and ch[0] != ch[len(ch)-1]:
        return False
    elif e==-1 and ch[0] == ch[len(ch)-1]:
        return True
    elif e!=-1 and ch[0] !=ch[e - 1]:
        return False
    else :
        return total_gramme(ch[e + 1:])


# pp
ch = input("ch= ")
print(total_gramme(ch))

